<script setup lang="ts">
import { shopCheckboxPrefix, checkboxAuthorityValid, checkboxNotice, checkboxMoney, checkboxReason, checkboxOperationStatus, checkboxOperationUuid, checkboxCandidateValid, useCheckboxRead, useCheckboxCommand } from '~/utils/shopCheckboxFiscal'
import type { CheckboxReadiness, CheckboxOperation } from '~/utils/shopCheckboxFiscal'
const props = defineProps<{ refreshToken?: number, profileReady?: boolean }>()
const emit = defineEmits<{ changed: [] }>()
const auth = useAuthStore(), api = useApi(), context = () => JSON.stringify([auth.user])
const read = useCheckboxRead<CheckboxReadiness>(context, () => auth.user?.id ? api(`${shopCheckboxPrefix}/readiness`, { retry: 0 }) : Promise.reject(new Error('No actor')), value => value.profile === 'checkbox' && !!value.actions && (!value.register || (checkboxAuthorityValid(value.register) && !!value.register.actions && Array.isArray(value.register.reports))), value => JSON.stringify([value.register?.id || value.profile_id, value.authority, value.transport]))
const { state, loading, error } = read
const register = computed(() => state.value?.register), registerId = () => register.value?.id || state.value?.profile_id || undefined
interface InitialBody { expected_profile_id: string, expected_revision?: number, confirm: true }
const verify = useCheckboxCommand<InitialBody>('verify', 'register', registerId), open = useCheckboxCommand<InitialBody>('shift-open', 'register', registerId), close = useCheckboxCommand<InitialBody>('shift-close', 'register', registerId), x = useCheckboxCommand<InitialBody>('x', 'register', registerId), z = useCheckboxCommand<InitialBody>('z', 'register', registerId)
const initial = { verify, open, close, x, z }
interface OperationBody { operation_id: number, expected_revision: number, candidate_report_uuid?: string, evidence?: string }
const process = useCheckboxCommand<OperationBody>('operation-process', 'register', registerId), reconcile = useCheckboxCommand<OperationBody>('operation-reconcile', 'register', registerId), cancel = useCheckboxCommand<OperationBody>('operation-cancel', 'register', registerId)
const operationCommands = { process, reconcile, cancel }, list = [...Object.values(initial), process, reconcile, cancel]
const busy = computed(() => list.some(command => command.busy.value)), unresolved = computed(() => list.some(command => command.intent.value))
const selectedOperation = shallowRef<CheckboxOperation | null>(null), recoveryError = ref(''), confirmed = ref(false), kind = ref<'x' | 'z'>('x'), candidate = ref(''), cancelEvidence = ref('')
const pendingOperationId = computed(() => [process, reconcile, cancel].find(command => command.intent.value)?.intent.value?.body.operation_id || Object.values(initial).find(command => command.intent.value?.resultId)?.intent.value?.resultId)
const operation = computed(() => { const id = pendingOperationId.value; return id ? (register.value?.pending_operation?.id === id ? register.value.pending_operation : selectedOperation.value?.id === id ? selectedOperation.value : register.value?.reports.find(item => item.id === id)) : selectedOperation.value || register.value?.pending_operation })
const registerOperation = (value: CheckboxOperation) => !['sale', 'return'].includes(value.kind) && value.order_id === null && value.document_id === null
let operationSequence = 0
const hydrateOperation = async (id: number, expectedKinds?: string[]) => {
  const version = read.version(), sequence = ++operationSequence
  try { const value = await api<CheckboxOperation>(`${shopCheckboxPrefix}/operations/${id}`, { retry: 0 }); if (!read.current(version) || sequence !== operationSequence) return false; if (!checkboxAuthorityValid(value) || value.id !== id || !registerOperation(value) || (expectedKinds && !expectedKinds.includes(value.kind)) || !value.actions) throw new Error('Invalid saved register operation'); selectedOperation.value = value; recoveryError.value = ''; return true }
  catch { if (read.current(version) && sequence === operationSequence) { selectedOperation.value = null; recoveryError.value = 'Не вдалося відновити оригінальну операцію профілю. Точний запит збережено.' } return false }
}
watch([pendingOperationId, () => state.value], () => { if (state.value && pendingOperationId.value && register.value?.pending_operation?.id !== pendingOperationId.value) void hydrateOperation(pendingOperationId.value) })
watch(context, () => { operationSequence++; selectedOperation.value = null; recoveryError.value = ''; confirmed.value = false; candidate.value = ''; cancelEvidence.value = '' }, { immediate: true, flush: 'sync' })
watch([kind, () => register.value?.revision, () => operation.value?.revision], () => { confirmed.value = false }, { flush: 'sync' })
watch(reconcile.intent, saved => { if (saved) candidate.value = saved.body.candidate_report_uuid || '' }, { immediate: true, flush: 'post' })
watch(cancel.intent, saved => { if (saved) cancelEvidence.value = saved.body.evidence || '' }, { immediate: true, flush: 'post' })
watch(() => props.refreshToken, () => { if (auth.user?.id) void read.load() })
onScopeDispose(() => { operationSequence++ })
const canInitial = (name: keyof typeof initial) => { const command = initial[name]; const actions = name === 'verify' ? state.value?.actions : register.value?.actions; return props.profileReady !== false && !!command.register.value && (!!command.intent.value?.resultId || (command.register.value === registerId() && (!command.intent.value || command.intent.value.body.expected_profile_id === registerId()))) && !!state.value && !loading.value && !busy.value && !(unresolved.value && !command.intent.value) && actions?.[command.intent.value ? `replay_${name}` : name] === true }
const send = async (name: keyof typeof initial) => {
  const command = initial[name]
  if (!canInitial(name) || (!command.intent.value && !confirmed.value) || (name !== 'verify' && !register.value)) return
  const version = read.version(), target = name === 'verify' ? '/verify' : name === 'open' || name === 'close' ? `/shift/${name}` : `/reports/${name}`
  const expectedKinds = name === 'open' ? ['shift_open'] : name === 'close' || name === 'z' ? ['shift_close', 'z'] : [name]
  confirmed.value = false
  await command.execute(name === 'verify' ? { expected_profile_id: registerId()!, confirm: true } : { expected_profile_id: registerId()!, expected_revision: register.value!.revision, confirm: true }, (body, key) => api<CheckboxOperation>(shopCheckboxPrefix + target, { method: 'POST', body, headers: { 'Idempotency-Key': key }, retry: 0 }), async id => { if (!read.current(version)) return; if (!await read.load() || !read.current(version) || !await hydrateOperation(id, expectedKinds)) throw new Error('Canonical operation unavailable'); if (!read.current(version)) return; command.clear(); emit('changed') })
  if (read.current(version) && !command.intent.value && command.error.value) await read.load()
}
const canOperation = (name: keyof typeof operationCommands) => { const saved = operationCommands[name].intent.value; return props.profileReady !== false && !!state.value && !!operation.value && registerOperation(operation.value) && !loading.value && !busy.value && !(unresolved.value && !saved) && (!saved || saved.body.operation_id === operation.value.id) && operation.value.actions[saved ? `replay_${name}` : name] === true }
const needsCandidate = computed(() => operation.value?.kind === 'x' && operation.value.status === 'unknown')
const runOperation = async (name: keyof typeof operationCommands) => {
  const command = operationCommands[name]
  if (!canOperation(name) || !operation.value || (!command.intent.value && ((name === 'reconcile' && needsCandidate.value && !checkboxCandidateValid(candidate.value.trim())) || (name === 'cancel' && !cancelEvidence.value.trim())))) return
  const version = read.version(), id = operation.value.id
  const body: OperationBody = command.intent.value?.body || { operation_id: id, expected_revision: operation.value.revision, ...(name === 'reconcile' && needsCandidate.value ? { candidate_report_uuid: candidate.value.trim() } : {}), ...(name === 'cancel' ? { evidence: cancelEvidence.value.trim() } : {}) }
  await command.execute(body, (saved, key) => { const { operation_id, ...request } = saved; return api<CheckboxOperation>(`${shopCheckboxPrefix}/operations/${operation_id}/${name}`, { method: 'POST', body: request, headers: { 'Idempotency-Key': key }, retry: 0 }) }, async resultId => { if (!read.current(version)) return; if (resultId !== id || !await read.load() || !read.current(version) || !await hydrateOperation(id)) throw new Error('Original operation unavailable'); if (!read.current(version)) return; command.clear(); candidate.value = ''; cancelEvidence.value = ''; emit('changed') })
  if (read.current(version) && !command.intent.value && command.error.value) await read.load()
}
const reload = async () => { if (await read.load() && pendingOperationId.value) await hydrateOperation(pendingOperationId.value) }
const totals = (value: CheckboxOperation) => {
  const closingReport = value.result?.z_report
  const raw = value.kind === 'x' ? value.result?.totals : ['z', 'shift_close'].includes(value.kind) && closingReport && typeof closingReport === 'object' ? (closingReport as Record<string, unknown>).totals : null
  if (value.status !== 'accepted' || !value.acceptance_verified || !raw || typeof raw !== 'object') return null
  const data = raw as Record<string, unknown>
  return ['sales_minor', 'returns_minor', 'net_minor', 'sale_count', 'return_count'].every(key => Number.isSafeInteger(data[key])) ? data as { sales_minor: number, returns_minor: number, net_minor: number, sale_count: number, return_count: number } : null
}
</script>
<template>
  <section aria-label="Профіль і зміна Checkbox" class="space-y-4 rounded-[1.75rem] border border-violet-200 bg-white p-6 text-slate-900">
    <h2 class="text-xl font-semibold">Профіль і зміна Checkbox</h2><p v-if="state" class="rounded-xl bg-amber-100 p-3 font-semibold text-amber-950" role="status">{{ checkboxNotice(state) }}</p><BaseButton variant="neutral" :disabled="loading || busy" @click="reload">Оновити профіль Checkbox</BaseButton>
    <template v-if="state"><p>Ідентичність {{ state.identity_verified ? 'перевірено сервером' : 'не підтверджено' }} · фіскальна політика {{ state.policy_available ? 'доступна' : 'не підтверджена' }}</p><p v-if="Object.values(initial).some(command => command.intent.value && !command.intent.value.resultId && command.register.value !== registerId())" role="alert">Збережений запит належить іншому профілю. Повтор заблоковано; відновіть оригінальний серверний профіль. Новий запит не створюється.</p><p v-for="code in state.blocking_reasons" :key="code">{{ checkboxReason(code) }}</p><p v-if="register">Профіль {{ register.id }} · revision {{ register.revision }} · зміна {{ register.shift_status === 'open' ? 'відкрита' : register.shift_status === 'closed' ? 'закрита' : 'результат невідомий' }} · {{ register.shift_id || 'UUID зміни ще не підтверджено' }}</p><p>Погодження створює локальну операцію в черзі. Запит провайдеру виконується лише окремою кнопкою обробки. Закриття зміни й Z мають один результат; окреме повторне створення Z не виконується.</p>
      <BaseCheckbox v-model="confirmed" label="Підтверджую явну операцію з поточним профілем Checkbox." :disabled="loading || busy || unresolved" /><BaseButton v-if="state.actions.verify || verify.intent.value" :disabled="!canInitial('verify') || (!verify.intent.value && !confirmed)" @click="send('verify')">{{ verify.intent.value ? 'Повторити ту саму перевірку профілю' : 'Погодити перевірку профілю Checkbox' }}</BaseButton><BaseButton v-if="register?.actions.open || open.intent.value" :disabled="!canInitial('open') || (!open.intent.value && !confirmed)" @click="send('open')">{{ open.intent.value ? 'Повторити те саме відкриття Checkbox' : 'Погодити відкриття зміни Checkbox' }}</BaseButton><BaseButton v-if="register?.actions.close || close.intent.value" :disabled="!canInitial('close') || (!close.intent.value && !confirmed)" @click="send('close')">{{ close.intent.value ? 'Повторити те саме закриття Checkbox' : 'Погодити закриття зміни Checkbox / Z' }}</BaseButton>
      <BaseSelect id="checkbox-report-kind" v-model="kind" label="Звіт Checkbox" aria-labelledby="checkbox-report-kind-label" native :disabled="busy || unresolved"><option value="x">X — поточні підсумки</option><option value="z">Z — закриття зміни</option></BaseSelect><BaseButton v-if="register?.actions[kind] || initial[kind].intent.value" :disabled="!canInitial(kind) || (!initial[kind].intent.value && !confirmed)" @click="send(kind)">Погодити {{ kind.toUpperCase() }} Checkbox</BaseButton><BaseButton v-for="name in (['x','z'] as const)" v-show="initial[name].intent.value" :key="name" :disabled="!canInitial(name)" @click="send(name)">Повторити той самий {{ name.toUpperCase() }} Checkbox</BaseButton>
      <article v-if="operation" :aria-label="`Операція Checkbox #${operation.id}`" class="space-y-3 border-t pt-4"><h3 class="font-semibold">Операція #{{ operation.id }} · {{ operation.kind }}</h3><p>{{ checkboxNotice(operation) }}</p><p role="status">{{ checkboxOperationStatus(operation) }}</p><p class="break-all">UUID {{ checkboxOperationUuid(operation) || 'Власний UUID запиту не створювався' }} · {{ operation.shift_id || 'Зміну не підтверджено' }}</p><p v-if="operation.result?.status">Статус провайдера (не замінює перевірений доказ): {{ operation.result.status }}</p><p v-for="code in operation.blocking_reasons" :key="code">{{ checkboxReason(code) }}</p><p v-if="!registerOperation(operation)">Пов’язаний чек замовлення #{{ operation.order_id }} обробляється у його фіскальній панелі.</p><BaseButton v-if="registerOperation(operation) && (operation.actions.process || process.intent.value)" :disabled="!canOperation('process')" @click="runOperation('process')">{{ process.intent.value ? 'Повторити ту саму обробку операції Checkbox' : 'Обробити операцію Checkbox' }}</BaseButton><template v-if="registerOperation(operation) && (operation.actions.reconcile || reconcile.intent.value)"><template v-if="needsCandidate"><p>Для невідомого X введіть лише вже знайдений UUID звіту. Сервер виконає читання та перевірить належність, час і суми; введення UUID не підтверджує звіт і не створює новий.</p><BaseInput v-model="candidate" label="Знайдений UUID звіту X для перевірки" :disabled="busy || unresolved" /></template><BaseButton :disabled="!canOperation('reconcile') || (!reconcile.intent.value && needsCandidate && !checkboxCandidateValid(candidate.trim()))" @click="runOperation('reconcile')">{{ reconcile.intent.value ? 'Повторити ту саму звірку операції Checkbox' : 'Звірити операцію Checkbox' }}</BaseButton></template><template v-if="registerOperation(operation) && (operation.actions.cancel || cancel.intent.value)"><BaseInput v-model="cancelEvidence" label="Підстава скасування операції Checkbox" :disabled="busy || unresolved" /><BaseButton :disabled="!canOperation('cancel') || (!cancel.intent.value && !cancelEvidence.trim())" @click="runOperation('cancel')">{{ cancel.intent.value ? 'Повторити те саме скасування операції Checkbox' : 'Скасувати непередану операцію Checkbox' }}</BaseButton></template></article>
      <article v-if="register?.reconciliation" aria-label="Звірка Checkbox" class="space-y-2 border-t pt-4"><p>Незавершені операції: {{ register.reconciliation.pending_operation_ids.join(', ') || 'немає' }}</p><p>Оплати без чека: {{ register.reconciliation.unreceipted_payment_ids.join(', ') || 'немає' }}</p><p>Незавершені повернення: {{ register.reconciliation.unresolved_return_ids.join(', ') || 'немає' }}</p><p v-if="register.reconciliation.unresolved_np_return_ids?.length">Незавершені повернення НП: {{ register.reconciliation.unresolved_np_return_ids.join(', ') }}. До окремої звірки випадків закриття зміни недоступне.</p><p v-if="register.reconciliation.unresolved_payment_resolution_ids?.length">Незавершені скасування та платіжні звірки: {{ register.reconciliation.unresolved_payment_resolution_ids.join(', ') }}. Закриття зміни потребує окремої перевірки цих випадків.</p></article>
      <article v-for="report in register?.reports || []" :key="report.id" :aria-label="`Звіт Checkbox #${report.id}`" class="space-y-2 border-t pt-4"><h3 class="font-semibold">{{ report.kind.toUpperCase() }} #{{ report.id }}</h3><p>{{ checkboxNotice(report) }} · {{ checkboxOperationStatus(report) }}</p><p v-if="report.kind === 'x' && checkboxOperationUuid(report)" class="break-all">Перевірений UUID звіту X {{ checkboxOperationUuid(report) }}</p><p v-if="totals(report)">Продажі {{ totals(report)!.sale_count }} / {{ checkboxMoney(totals(report)!.sales_minor) }} · повернення {{ totals(report)!.return_count }} / {{ checkboxMoney(totals(report)!.returns_minor) }} · підсумок {{ checkboxMoney(totals(report)!.net_minor) }}</p><p v-else>Підсумки ще не підтверджено перевіреним доказом.</p></article>
    </template><p v-for="message in [error, recoveryError, ...list.map(command => command.error.value)].filter(Boolean)" :key="message" role="alert">{{ message }}</p>
  </section>
</template>
